import 'package:flutter/material.dart';
import '../services/gemini_service.dart';
import 'ai_settings_screen.dart';
class CurrentAffairsScreen extends StatefulWidget{const CurrentAffairsScreen({super.key});@override State<CurrentAffairsScreen> createState()=>_CurrentAffairsScreenState();}
class _CurrentAffairsScreenState extends State<CurrentAffairsScreen>{String text='';bool loading=false;String category='All';final cats=['All','India','World','Economy','Science','Sports','Awards'];
 Future<void> refresh()async{if(!await GeminiService.configured()){if(mounted)Navigator.push(context,MaterialPageRoute(builder:(_)=>const AISettingsScreen()));return;}setState(()=>loading=true);try{final now=DateTime.now();final prompt='Today is '+now.toIso8601String().substring(0,10)+'. Give exam-focused '+category+' current affairs useful for SSC CGL, SSC CHSL, RRB NTPC, Banking and State PSC aspirants in India. Give 10 concise exam-focused items with date, what happened, why it matters, and one possible MCQ fact. Do not invent anything.';final ans=await GeminiService.ask(input:prompt,webSearch:true);if(mounted)setState(()=>text=ans);}catch(e){if(mounted)setState(()=>text='Could not load live current affairs: '+e.toString());}finally{if(mounted)setState(()=>loading=false);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Live Current Affairs V2'),actions:[IconButton(onPressed:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>const AISettingsScreen())),icon:const Icon(Icons.settings_rounded))]),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Gemini Current Affairs',style:TextStyle(fontSize:22,fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('AI-generated exam current affairs. Verify time-sensitive facts from official sources.'),const SizedBox(height:14),Wrap(spacing:8,runSpacing:8,children:cats.map((x)=>ChoiceChip(label:Text(x),selected:category==x,onSelected:(_)=>setState(()=>category=x))).toList()),const SizedBox(height:14),FilledButton.icon(onPressed:loading?null:refresh,icon:const Icon(Icons.travel_explore_rounded),label:Text(loading?'Generating...':'Generate current affairs')),if(loading)const Padding(padding:EdgeInsets.only(top:16),child:LinearProgressIndicator()),if(text.isNotEmpty)Padding(padding:const EdgeInsets.only(top:18),child:SelectableText(text,style:const TextStyle(height:1.5)))]));}
